# DK LAL.  Lindholm - Aalborg Lufthavn
#
let ll = path("d3.dk.lal");

with detail = 4, railway = :first :pax {
    # point.dk.Lindholm  dk.FFH

    with link = "line.dk.LAL" {
        track(:station,
                ll[:lin.yl - 0.1dl, :lin.yl] << 1mo
            ..  ll[:lin.xl + 1mo, :lin.xl + 1.1mo]
        );
        track(ll[:lin.xl + 1mo, :lin.yl + 1.21km]);
        line_label(:left:n, ll[:lin.yl + 1.2km] << 0.5mt, "LAL");
        track(ll[:lin.yl + 1.19km, :alu - 0.49sw]);
    }

    with link = "point.dk.Aalborg-Lufthavn", railway = :station {
        track(ll[:alu - 0.5sw, :alu + 0.5sw]);
        marker(:left :de.bf, ll[:alu] << 0.5mt);
        station(:left, ll[:alu] << 0.5mt << 1sh + (-2dt, 1.8dt),
            span(:bold, "Aalborg Lufthavn"), "LAL: 254,167"
        );
    }
}


